  let startupError, ws, closing;
  chrome.on("error", (error) => { startupError = error; });
  const exited = new Promise((resolve) => {
    chrome.once("exit", resolve);
    chrome.once("error", resolve);
  });
  const close = () => closing ??= (async () => {
    try { ws?.close(); } catch {}
    if (chrome.exitCode === null && chrome.signalCode === null && !startupError) {
      chrome.kill();
      if (!await Promise.race([exited.then(() => true), delay(2000).then(() => false)])) {
        chrome.kill("SIGKILL");
        await exited;
      }
    }
    rmSync(userDataDir, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 });
  })();

  try {
    let endpoint;
    for (let i = 0; i < 80 && !endpoint; i++) {
      await delay(100);
      if (startupError) throw startupError;
      if (chrome.exitCode !== null || chrome.signalCode !== null) throw new Error("Chrome exited before devtools became ready");
      let activePort;
      try { activePort = readFileSync(join(userDataDir, "DevToolsActivePort"), "utf8"); }
      catch (error) { if (error.code === "ENOENT") continue; throw error; }
      const [port, browserPath] = activePort.trim().split("\n");
      if (!/^[0-9]+$/.test(port) || Number(port) < 1 || Number(port) > 65535 ||
          !/^\/devtools\/browser\/[a-zA-Z0-9-]+$/.test(browserPath)) {
        throw new Error("Invalid Chrome DevToolsActivePort");
      }
      endpoint = `ws://127.0.0.1:${port}${browserPath}`;
    }
    if (!endpoint) throw new Error("Chrome devtools endpoint not ready");

    ws = new WebSocket(endpoint);
    await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; ws.onclose = () => rej(new Error("Chrome devtools connection closed")); });
    let id = 0, sessionId;
    const inflight = new Map(), events = [];
    const rejectPending = () => {
      for (const request of inflight.values()) request.reject(new Error("Chrome devtools connection closed"));
      inflight.clear();
    };
    ws.onerror = rejectPending;
    ws.onclose = rejectPending;
    ws.onmessage = (ev) => {
